import itertools

def is_costas(perm):
    n = len(perm)
    # For each distance d, check differences are unique
    for d in range(1, n):
        diffs = set()
        for i in range(n - d):
            diff = perm[i+d] - perm[i]
            if diff in diffs:
                return False
            diffs.add(diff)
    return True

n = 9
found = None
for perm in itertools.permutations(range(n)):
    if is_costas(perm):
        found = perm
        break

print(found)
